import type { CSSProperties } from "react"
import { getLineAriaLabel } from "tfl-ts"
import { CHIP_CAP_TEXT_BOX_CLASS } from "@/components/tfl/arrivals/chip-text"
import { LineName } from "@/components/tfl/brand/line-name"
import { TFL_BLUE } from "@/lib/tfl/brand-colours"
import { getLineColourToken } from "@/lib/tfl/line-colour-map"
import { getLineNameTiers, joinLineNames } from "@/lib/tfl/line-names"
import {
  resolveRouteTrackStyle,
  routeTrackRailCount,
  type RouteTrackStyle,
} from "@/lib/tfl/route-track"
import { cn } from "@/lib/utils"
import { Skeleton } from "@/components/ui/skeleton"

type LineStatusLike = {
  statusSeverity?: number
  statusSeverityDescription?: string
}

type LineBadgeProps = {
  lineId: string
  name?: string
  lineStatuses?: LineStatusLike[]
  className?: string
  /** Show a filled colour chip (default) or text-only with brand colour. */
  variant?: "chip" | "text"
  /**
   * Explicit brand colour when `lineId` is not in the token set.
   * Sets `--line-raw` inline.
   */
  color?: string
  /**
   * Use diagram paint when it differs from mode identity
   * (Cable Car map red instead of purple).
   */
  diagram?: boolean
  /**
   * `clip` (default) — paint the full name, let the parent clip.
   * `shrink` — step full → middle → short via `LineName` (chips may wrap).
   */
  fit?: "clip" | "shrink"
}

/**
 * `--line-raw` override for ids outside the token palette.
 * Known ids must keep the CSS binding so `.dark` can swap Northern.
 */
const lineRawStyle = (
  lineId: string | undefined,
  color?: string
): CSSProperties | undefined =>
  color && !(lineId && getLineColourToken(lineId))
    ? ({ "--line-raw": color } as CSSProperties)
    : undefined

/** Skeleton for a line badge chip — use in `loading.tsx` or Suspense. */
export const LineBadgeSkeleton = ({ className }: { className?: string }) => (
  <Skeleton className={cn("inline-flex h-5 w-16", className)} aria-hidden />
)

/** Skeleton grid matching the line badge demo page. */
export const LineBadgeBoardSkeleton = () => (
  <div className="w-full space-y-8" aria-busy aria-label="Loading line badges">
    <div className="space-y-2">
      <Skeleton className="h-9 w-40 max-w-full" />
      <Skeleton className="h-4 w-full max-w-lg" />
    </div>
    <div className="flex flex-wrap gap-2">
      {Array.from({ length: 12 }).map((_, i) => (
        <LineBadgeSkeleton key={i} />
      ))}
    </div>
    <div className="grid grid-cols-2 gap-x-3 gap-y-4 sm:grid-cols-4">
      {Array.from({ length: 8 }).map((_, i) => (
        <Skeleton key={i} className="h-10 w-full" />
      ))}
    </div>
  </div>
)

/**
 * Official TfL line colour badge.
 * Colours resolve via `data-line` → `--line-color` / `--line-ink` from tfl-colours.
 * Northern dark mode uses a white fill token (no shadow outline).
 */
export const LineBadge = ({
  lineId,
  name,
  lineStatuses,
  className,
  variant = "chip",
  color,
  diagram,
  fit = "clip",
}: LineBadgeProps) => {
  const label = name ?? getLineNameTiers(lineId).full
  const ariaLabel =
    lineStatuses && lineStatuses.length > 0
      ? getLineAriaLabel(label, lineStatuses)
      : `${label} line`
  const style = lineRawStyle(lineId, color)
  const namePaint =
    fit === "shrink" ? (
      <LineName lineId={lineId} name={name ?? label} wrap />
    ) : (
      label
    )

  if (variant === "text") {
    return (
      <span
        data-line={lineId}
        data-tfl-diagram={diagram ? "" : undefined}
        className={cn(
          "font-semibold text-[var(--line-color)]",
          fit === "shrink" && "inline-block w-full min-w-0",
          className
        )}
        style={style}
        aria-label={ariaLabel}
      >
        {namePaint}
      </span>
    )
  }

  return (
    <span
      data-line={lineId}
      data-tfl-diagram={diagram ? "" : undefined}
      className={cn(
        "inline-flex h-5 items-center bg-[var(--line-color)] px-2 text-xs font-bold text-[var(--line-ink)] tabular-nums",
        fit === "shrink" && "w-full max-w-full min-w-0",
        className
      )}
      style={{ border: "var(--line-border, none)", ...style }}
      aria-label={ariaLabel}
      role="img"
    >
      {fit === "shrink" ? (
        <LineName
          lineId={lineId}
          name={name ?? label}
          wrap
          className={CHIP_CAP_TEXT_BOX_CLASS}
        />
      ) : (
        <span className={CHIP_CAP_TEXT_BOX_CLASS}>{label}</span>
      )}
    </span>
  )
}

export type LineBadgeGroupAlign = "left" | "right" | "center"
/** `auto` = shrink-wrap label (side fill). `under` = full-width floating label. */
export type LineBadgeGroupStripes = "auto" | "under"
/**
 * `label` (default) — TfL blue plate over the colour stack.
 * `codes` — same-height stripe stack; 3-letter abbrs take turns (CSS).
 * Fixed `5ch` so it aligns with `BusNumberChip` and single-line code chips.
 */
export type LineBadgeGroupVariant = "label" | "codes"

export type LineBadgeGroupProps = {
  /** Line ids to paint as one shared-track label. Prefer ≤3. */
  lineIds: readonly string[]
  /** Optional per-id name overrides aligned with `lineIds`. */
  names?: readonly string[]
  className?: string
  /**
   * `label` (default) — blue plate + shared name.
   * `codes` — stripe stack at chip height; one 3-letter abbr at a time
   * in a fixed `5ch` box.
   */
  variant?: LineBadgeGroupVariant
  /**
   * Text alignment. Also inferred from `className` (`text-left` /
   * `text-right` / `text-center`) when omitted. Default `left`.
   */
  align?: LineBadgeGroupAlign
  /**
   * `auto` (default) — shrink-wrap the TfL blue label so stripes fill the side.
   * `under` — full-width text on the stripe field, no blue plate.
   * Ignored when `variant` is `codes`.
   */
  stripes?: LineBadgeGroupStripes
}

const parseAlignFromClassName = (
  className: string | undefined
): LineBadgeGroupAlign | undefined => {
  if (!className) return undefined
  if (/(?:^|\s)(?:text-center|justify-center)(?:\s|$)/.test(className)) {
    return "center"
  }
  if (/(?:^|\s)(?:text-right|justify-end)(?:\s|$)/.test(className)) {
    return "right"
  }
  if (/(?:^|\s)(?:text-left|justify-start)(?:\s|$)/.test(className)) {
    return "left"
  }
  return undefined
}

/**
 * Shared-track chip — pure CSS.
 *
 * Full-bleed vertical colour stack behind. TfL blue label floats on top and
 * shrink-wraps (`w-fit`) so stripes fill the open side (left→right tip,
 * right→left tip; center→both). When the name would cover the chip, a thin
 * `0.25rem` tip stays on the open side(s). Abbreviation steps against the
 * plate budget. Ladder: full → middle → short (no wrap). When too narrow
 * for a plate, the blue fill drops so stripes show through.
 */
export const LineBadgeGroup = ({
  lineIds,
  names,
  className,
  variant = "label",
  align: alignProp,
  stripes = "auto",
}: LineBadgeGroupProps) => {
  const fullNames = lineIds.map(
    (id, index) => getLineNameTiers(id, names?.[index]).full
  )
  const ariaLabel = joinLineNames(fullNames)
  const ids = lineIds.length > 0 ? lineIds : ["underground"]
  const align = alignProp ?? parseAlignFromClassName(className) ?? "left"
  const forceUnder = stripes === "under"
  const noPlate = stripes === "under"

  if (variant === "codes") {
    const shorts = ids.map(
      (id, index) => getLineNameTiers(id, names?.[index]).short
    )
    const codeCount = Math.min(Math.max(shorts.length, 1), 3)

    return (
      <span
        className={cn(
          "tfl-line-codes relative inline-flex h-5 w-[5ch] shrink-0 items-center justify-center overflow-hidden text-xs font-bold tabular-nums",
          className
        )}
        style={{ "--codes-count": codeCount } as CSSProperties}
        data-codes={codeCount}
        aria-label={ariaLabel}
        role="img"
      >
        <span className="absolute inset-0 flex flex-col" aria-hidden>
          {ids.map((id) => (
            <span
              key={id}
              data-line={id}
              className="min-h-0 min-w-0 flex-1 bg-[var(--line-color)]"
            />
          ))}
        </span>
        <span
          className="relative z-10 grid w-full place-items-center text-white"
          aria-hidden
        >
          {shorts.map((code, index) => (
            <span
              key={`${ids[index]}-${code}`}
              data-code={code}
              className={cn(
                "col-start-1 row-start-1 text-center",
                CHIP_CAP_TEXT_BOX_CLASS
              )}
              style={{ "--code-index": index } as CSSProperties}
            >
              {code}
            </span>
          ))}
        </span>
      </span>
    )
  }

  return (
    <span
      className={cn(
        // Chip size for the stripe-tip calc (`100cqi` below).
        "@container/chip relative inline-flex w-full max-w-full min-w-0 items-center overflow-hidden text-xs font-bold tabular-nums",
        className
      )}
      aria-label={ariaLabel}
      role="img"
    >
      <span className="absolute inset-0 flex flex-col" aria-hidden>
        {ids.map((id) => (
          <span
            key={id}
            data-line={id}
            className="min-h-0 min-w-0 flex-1 bg-[var(--line-color)]"
          />
        ))}
      </span>

      {/* Full-width measure box — plate packs to the aligned edge. */}
      <span
        className={cn(
          "@container/line-name relative z-10 flex w-full min-w-0",
          align === "right" && "justify-end",
          align === "center" && "justify-center"
        )}
      >
        <span
          className={cn(
            "px-2 leading-5 text-white",
            // Cap long names so a tip of stripe stays on the open side(s).
            forceUnder
              ? "w-full bg-transparent"
              : "w-fit max-w-[calc(100cqi-0.25rem)] bg-[var(--line-group-plate)]",
            align === "center" && "text-center",
            align === "right" && "text-right",
            align === "left" && "text-left",
            !noPlate &&
              // Too tight for a plate — drop blue fill instead of wrapping.
              "@max-[10rem]/line-name:bg-transparent @max-[10rem]/line-name:px-1"
          )}
          style={
            noPlate
              ? undefined
              : ({ "--line-group-plate": TFL_BLUE } as CSSProperties)
          }
        >
          <LineName
            lineIds={lineIds}
            names={names}
            group
            establishContainer={false}
          />
        </span>
      </span>
    </span>
  )
}

const resolveColorBarTrackStyle = (
  lineId?: string,
  modeName?: string
): RouteTrackStyle => {
  if (modeName === "cable-car") return "cable-car"
  if (modeName === "overground" || modeName === "elizabeth-line") {
    return "parallel"
  }
  if (lineId) return resolveRouteTrackStyle(lineId)
  return "solid"
}

/** Horizontal brand colour bar; Overground / Elizabeth / Cable Car get rail stacks. */
export const LineColorBar = ({
  lineId,
  modeName,
  heightClass = "h-[4px]",
  color,
  diagram,
}: {
  lineId?: string
  modeName?: string
  heightClass?: string
  /** Explicit brand colour when `lineId` is not in the token set. */
  color?: string
  /**
   * Use diagram paint when it differs from mode identity
   * (Cable Car map red instead of purple).
   */
  diagram?: boolean
}) => {
  const rails = routeTrackRailCount(resolveColorBarTrackStyle(lineId, modeName))
  const style = lineRawStyle(lineId, color)
  const dataLine = lineId || undefined
  const bands: { key: string; fill: boolean }[] = []
  for (let i = 0; i < rails; i += 1) {
    bands.push({ key: `rail-${i}`, fill: true })
    if (i < rails - 1) {
      bands.push({ key: `gap-${i}`, fill: false })
    }
  }

  return (
    <div
      data-line={dataLine}
      data-tfl-diagram={diagram ? "" : undefined}
      className={cn(
        rails === 1 ? "relative w-full" : "flex w-full flex-col",
        heightClass
      )}
      style={style}
      aria-hidden
    >
      {rails === 1 ? (
        <div className="h-full w-full bg-[var(--line-color)]" />
      ) : (
        bands.map((band) => (
          <div
            key={band.key}
            className={cn(
              "min-h-0 w-full flex-1",
              band.fill && "bg-[var(--line-color)]"
            )}
          />
        ))
      )}
    </div>
  )
}

import { FindableText } from "@/components/tfl/findable-text"
import {
  getLineNameTiers,
  joinLineNames,
  type LineNameTiers,
  type LineNameWidthBucket,
} from "@/lib/tfl/line-names"
import { cn } from "@/lib/utils"

export type LineNameProps = {
  /** Single line id — mutually exclusive with `lineIds`. */
  lineId?: string
  /** Explicit display name override / fallback for unknown ids. */
  name?: string
  /**
   * Multiple line ids for the shared-track convention
   * (e.g. Circle + H&C + Metropolitan). Mutually exclusive with `lineId`.
   */
  lineIds?: readonly string[]
  /** Optional per-id name overrides aligned with `lineIds`. */
  names?: readonly string[]
  className?: string
  /**
   * When true, allow a 2-line form only when there is no useful middle
   * abbreviation. Prefer full → middle → short; never stack tiers.
   * Shared-track groups ignore wrap (plate drops instead). Status board
   * headers keep `false`.
   */
  wrap?: boolean
  /**
   * Wider breakpoints — forced on when `lineIds` is set.
   */
  group?: boolean
  /**
   * When true (default), this node is `@container/line-name` and fills its
   * parent — right for board headers. When false, parent must establish the
   * container (e.g. LineBadgeGroup’s plate budget); paint shrink-wraps so
   * chips can side-fill.
   */
  establishContainer?: boolean
}

type TierPaint = {
  full: string
  middle: string
  short: string
  bucket: LineNameWidthBucket
  hasMiddle: boolean
  canWrapFull: boolean
}

const resolvePaint = (
  lineId: string | undefined,
  name: string | undefined,
  lineIds: readonly string[] | undefined,
  names: readonly string[] | undefined
): TierPaint => {
  if (lineIds && lineIds.length > 0) {
    const tiers = lineIds.map((id, index) =>
      getLineNameTiers(id, names?.[index])
    )
    const full = joinLineNames(tiers.map((t) => t.full))
    const middle = joinLineNames(tiers.map((t) => t.middle))
    const short = tiers.map((t) => t.short).join("/")
    return {
      full,
      middle,
      short,
      bucket: "long",
      hasMiddle: middle !== full,
      canWrapFull: /\s/.test(full),
    }
  }

  const id = lineId ?? ""
  const tiers: LineNameTiers = getLineNameTiers(id, name)
  return {
    full: tiers.full,
    middle: tiers.middle,
    short: tiers.short,
    bucket: tiers.bucket,
    hasMiddle: tiers.middle !== tiers.full,
    canWrapFull: /\s/.test(tiers.full),
  }
}

/**
 * Exclusive visibility ladders — same idea as PlatformChip.
 * Use `hidden` / `block` only. Never put `line-clamp-*` on these nodes
 * (it sets `display: -webkit-box` and fights `hidden`).
 */
const tierClasses = (options: {
  bucket: LineNameWidthBucket
  wrap: boolean
  group: boolean
  hasMiddle: boolean
  canWrapFull: boolean
  /** Joined group size — 3-line names need a wider full band than pairs. */
  lineCount: number
}): {
  fullOneLine: string
  fullTwoLine: string | null
  middle: string | null
  short: string
} => {
  const { bucket, wrap, group, hasMiddle, canWrapFull, lineCount } = options
  // 2-line full form: when wrap is on and there is no useful middle abbr.
  const useWrap = wrap && canWrapFull && !hasMiddle

  if (group) {
    if (hasMiddle) {
      // Shared-track chips: full → middle → short. No wrap.
      // Pairs (e.g. Circle + H&C) get full sooner; triples need more width
      // and drop to CIR/H&C/MET earlier when the plate budget is tight.
      if (lineCount >= 3) {
        return {
          fullOneLine: "hidden whitespace-nowrap @min-[24rem]/line-name:block",
          fullTwoLine: null,
          middle:
            "hidden whitespace-nowrap @min-[12rem]/line-name:block @min-[24rem]/line-name:hidden",
          short: "block whitespace-nowrap @min-[12rem]/line-name:hidden",
        }
      }
      return {
        fullOneLine: "hidden whitespace-nowrap @min-[14rem]/line-name:block",
        fullTwoLine: null,
        middle:
          "hidden whitespace-nowrap @min-[8rem]/line-name:block @min-[14rem]/line-name:hidden",
        short: "block whitespace-nowrap @min-[8rem]/line-name:hidden",
      }
    }
    if (useWrap) {
      return {
        fullOneLine: "hidden whitespace-nowrap @min-[18rem]/line-name:block",
        fullTwoLine:
          "hidden @min-[9rem]/line-name:block @min-[18rem]/line-name:hidden",
        middle: null,
        short: "block whitespace-nowrap @min-[9rem]/line-name:hidden",
      }
    }
    return {
      fullOneLine: "hidden whitespace-nowrap @min-[10rem]/line-name:block",
      fullTwoLine: null,
      middle: null,
      short: "block whitespace-nowrap @min-[10rem]/line-name:hidden",
    }
  }

  if (bucket === "long") {
    if (hasMiddle) {
      // Full "Hammersmith & City" at board `text-xl` / 20px P22 is ~12.4rem.
      // 11rem still paints the full name and the status tile overflow-clips it.
      return {
        fullOneLine: "hidden whitespace-nowrap @min-[13rem]/line-name:block",
        fullTwoLine: null,
        middle:
          "hidden whitespace-nowrap @min-[4.5rem]/line-name:block @min-[13rem]/line-name:hidden",
        short: "block whitespace-nowrap @min-[4.5rem]/line-name:hidden",
      }
    }
    if (useWrap) {
      return {
        fullOneLine: "hidden whitespace-nowrap @min-[12rem]/line-name:block",
        fullTwoLine:
          "hidden @min-[6rem]/line-name:block @min-[12rem]/line-name:hidden",
        middle: null,
        short: "block whitespace-nowrap @min-[6rem]/line-name:hidden",
      }
    }
    return {
      fullOneLine: "hidden whitespace-nowrap @min-[11rem]/line-name:block",
      fullTwoLine: null,
      middle: null,
      short: "block whitespace-nowrap @min-[11rem]/line-name:hidden",
    }
  }

  if (bucket === "medium") {
    if (useWrap) {
      return {
        fullOneLine: "hidden whitespace-nowrap @min-[10rem]/line-name:block",
        fullTwoLine:
          "hidden @min-[5.5rem]/line-name:block @min-[10rem]/line-name:hidden",
        middle: null,
        short: "block whitespace-nowrap @min-[5.5rem]/line-name:hidden",
      }
    }
    return {
      fullOneLine: "hidden whitespace-nowrap @min-[8rem]/line-name:block",
      fullTwoLine: null,
      middle: null,
      short: "block whitespace-nowrap @min-[8rem]/line-name:hidden",
    }
  }

  if (useWrap) {
    return {
      fullOneLine: "hidden whitespace-nowrap @min-[8rem]/line-name:block",
      fullTwoLine:
        "hidden @min-[4.5rem]/line-name:block @min-[8rem]/line-name:hidden",
      middle: null,
      short: "block whitespace-nowrap @min-[4.5rem]/line-name:hidden",
    }
  }
  return {
    fullOneLine: "hidden whitespace-nowrap @min-[6rem]/line-name:block",
    fullTwoLine: null,
    middle: null,
    short: "block whitespace-nowrap @min-[6rem]/line-name:hidden",
  }
}

/**
 * Smart line-name label. Steps full → middle (H&C / W&C) → 3-letter code
 * via `@container/line-name` queries — same CSS-first pattern as PlatformChip.
 *
 * Pass `lineIds` for the TfL shared-track convention
 * ("Circle, H&C and Metropolitan").
 */
export const LineName = ({
  lineId,
  name,
  lineIds,
  names,
  className,
  wrap = false,
  group = false,
  establishContainer = true,
}: LineNameProps) => {
  const isGroup = group || Boolean(lineIds && lineIds.length > 0)
  const paint = resolvePaint(lineId, name, lineIds, names)
  const lineCount = lineIds?.length ?? (lineId ? 1 : 0)
  const classes = tierClasses({
    bucket: paint.bucket,
    wrap,
    group: isGroup,
    hasMiddle: paint.hasMiddle,
    canWrapFull: paint.canWrapFull,
    lineCount,
  })

  return (
    <FindableText
      text={paint.full}
      className={cn(
        establishContainer
          ? "@container/line-name block w-full max-w-full min-w-0"
          : "inline-block w-fit max-w-full",
        className
      )}
    >
      <span className={classes.fullOneLine} aria-hidden>
        {paint.full}
      </span>
      {classes.fullTwoLine ? (
        <span className={classes.fullTwoLine} aria-hidden>
          {/* Clamp on the inner node so it cannot override display:none. */}
          <span className="line-clamp-2 text-pretty">{paint.full}</span>
        </span>
      ) : null}
      {classes.middle ? (
        <span className={classes.middle} aria-hidden>
          {paint.middle}
        </span>
      ) : null}
      <span className={classes.short} aria-hidden>
        {paint.short}
      </span>
    </FindableText>
  )
}

/**
 * Curated display tiers for TfL line names.
 *
 * Prefer full → middle (TfL short forms like H&C) → 3-letter code.
 * `bucket` drives which CSS container-query breakpoints `LineName` uses.
 *
 * Classic Underground short codes follow the table shipped with this library.
 * Elizabeth / DLR / Tram / Overground codes are best-effort first-3-letter
 * forms — adjust here when official abbreviations are confirmed.
 */

export type LineNameWidthBucket = "short" | "medium" | "long"

export type LineNameTiers = {
  full: string
  middle: string
  short: string
  bucket: LineNameWidthBucket
}

